/* Profile design review. Account and inbox changes are browser-only, not identity/OAuth APIs. */
let profileData={name:'Alex Morgan',email:'alex@example.com',phone:'+1 202 555 0143',dateOfBirth:'1993-03-14',gender:'Not set'};
let profileInboxes=[{id:'gmail-alex',email:'alex@example.com',status:'synced',lastSync:'26 Oct · 9:00 AM'}];
let profileReviewOrigin='Profile',profileDialogTrigger=null;
const profileGlyphs={edit:'m15 4 5 5M4 20l5-1L21 7l-4-4L5 15z',history:'M3 11a9 9 0 1 1 2 7M3 5v6h6M12 7v5l3 2',payments:'M3 7h18v13H3zM3 11h18M7 16h3',security:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6zM9 12l2 2 4-4',help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 2-3 4M12 17h.01',privacy:'M5 10h14v11H5zM8 10V7a4 4 0 0 1 8 0v3',terms:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7',delete:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',logout:'M9 4H4v16h5M14 8l4 4-4 4M8 12h10',sparkle:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',mail:'M3 5h18v14H3zM3 6l9 7 9-7',refresh:'M20 7v5h-5M4 17v-5h5M6 8a7 7 0 0 1 12-2l2 6M4 12l2 6a7 7 0 0 0 12-2',settings:'M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM19 12l2-1-2-4-2 1-2-1-1-2h-4l-1 2-2 1-2-1-2 4 2 1v0l-2 1 2 4 2-1 2 1 1 2h4l1-2 2-1 2 1 2-4z',widget:'M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z'};
const profileIcon=kind=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${profileGlyphs[kind]||profileGlyphs.help}"/>${kind==='help'?'<circle cx="12" cy="12" r="9"/>':''}</svg>`;
function profileContext(){const view=current.startsWith('Profile')?current:profileReviewOrigin;return {incomplete:view==='Profile · incomplete',hasPassword:view!=='Profile · social',provider:view==='Profile · social'?'Google':'Email'};}
function profileInitials(name){return name.trim().split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase()||'R';}
// Never-synced preview: the first inbox without a successful sync yet (native, 13 Nov 2026).
function profileInboxForView(){const inbox=profileInboxes[0];return inbox&&['Profile · not synced','Connected inbox · not synced'].includes(current)?{...inbox,lastSync:null}:inbox;}
function profileImportedRecords(email,records=subscriptionListData()){return records.filter(r=>r.source==='Gmail'&&r.inboxEmail===email);}
function profilePaymentText(){const totals={};for(const p of paymentRecords.values())totals[p.currency]=(totals[p.currency]||0)+Math.round(p.amount*100);return Object.keys(totals).length?Object.entries(totals).map(([currency,cents])=>uiMoney(currency,(cents/100).toFixed(2))).join(' · ')+' confirmed':'Confirmed payment history';}
function profileMenuRow(label,icon,{to='',action='',subtitle='',tone=''}={}){return `<button class="profile-menu-row ${tone}" ${to?`data-go="${to}"`:`data-profile-action="${action}"`}><span class="profile-menu-icon">${profileIcon(icon)}</span><span class="profile-menu-copy"><strong>${label}</strong>${subtitle?`<small>${escape(subtitle)}</small>`:''}</span><span class="profile-chevron" aria-hidden="true">›</span></button>`;}
function profileScreen(){
 profileReviewOrigin=current;const context=profileContext(),inbox=context.incomplete?null:profileInboxForView();
 return `<div class="profile-review"><div class="head"><h2>Profile</h2><button class="alerts-settings-icon" data-go="Settings" aria-label="Settings">${alertGear()}</button></div><div class="profile-account-header"><span class="profile-account-avatar" aria-hidden="true">${escape(profileInitials(profileData.name))}</span><div><h3>${escape(profileData.name)}</h3><p>${escape(profileData.email)}</p><small>Signed in with ${context.provider}</small></div><button class="profile-edit-icon" data-profile-action="edit" aria-label="Edit profile">${profileIcon('edit')}</button></div><section class="profile-inboxes"><div class="profile-section-heading"><h3>Connected inboxes</h3>${inbox?'<button data-profile-action="connect" aria-label="Connect another Gmail inbox">+ Connect</button>':''}</div>${inbox?`<button class="profile-inbox-row" data-profile-action="inbox"><span class="profile-inbox-logo">${platformLogo('Gmail')}</span><span class="profile-inbox-copy"><strong>${escape(inbox.email)}</strong><small class="${inbox.status==='synced'&&inbox.lastSync?'inbox-synced':'inbox-paused'}"><i aria-hidden="true"></i>${inbox.status==='reconnect'?'Reconnect needed':inbox.status!=='synced'?'Updates paused':inbox.lastSync?'Synced':'Not synced yet'}${inbox.lastSync?'<span class="profile-sync-time"> · Last sync 26 Oct</span>':''}</small></span><span class="profile-chevron" aria-hidden="true">›</span></button>`:`<div class="profile-no-inbox"><span>${profileIcon('mail')}</span><div><strong>No inbox connected</strong><p>Find subscriptions and keep them up to date.</p></div><button data-profile-action="connect">Connect</button></div>`}</section><section class="profile-menu-section" aria-label="Your activity"><h3>Your activity</h3><div class="profile-menu-group">${profileMenuRow('History','history',{to:'History',subtitle:'Cancelled & expired subscriptions'})}${profileMenuRow('Payment history','payments',{to:'Payments',subtitle:profilePaymentText()})}</div></section><section class="profile-menu-section" aria-label="More"><h3>More</h3><div class="profile-menu-group">${profileMenuRow('Settings','settings',{to:'Settings',subtitle:'Reminders, AI assistant, account'})}${profileMenuRow('Help & support','help',{action:'support'})}</div></section><button class="profile-logout" data-profile-action="logout">${profileIcon('logout')}<span>Log out</span></button><p class="profile-app-version">Renewless · Version 0.0.1</p></div>`;
}
function profileEditScreen(){const ctx=profileContext();return `<div class="profile-edit-review">${heading('Edit profile',true)}<p class="profile-edit-intro">Keep your account details up to date.</p><form data-profile-edit novalidate>${profileEditField('Name','name',profileData.name,'text',true)}<div class="profile-readonly-email"><span>Login email</span><strong>${escape(profileData.email)}</strong><p>Email changes require verification.</p></div>${profilePhoneField(ctx.incomplete?'':profileData.phone)}${profileEditField('Date of birth · Optional','dateOfBirth',ctx.incomplete?'':profileData.dateOfBirth,'date')}${selectField({label:'Gender · Optional',name:'gender',value:profileData.gender,options:['Not set','Female','Male','Other']})}<p class="profile-optional-note">Optional details are never required to use Renewless.</p><button class="primary" type="submit">Save changes</button></form></div>`;}
// Phone country picker (approved and locked 7 Nov 2026; native uses the full list in src/config/countries.ts): flag + dial code button opens a searchable country sheet.
const PROFILE_COUNTRIES=[['AU','Australia','61','🇦🇺'],['BD','Bangladesh','880','🇧🇩'],['CA','Canada','1','🇨🇦'],['FR','France','33','🇫🇷'],['DE','Germany','49','🇩🇪'],['IN','India','91','🇮🇳'],['NG','Nigeria','234','🇳🇬'],['PK','Pakistan','92','🇵🇰'],['SA','Saudi Arabia','966','🇸🇦'],['SG','Singapore','65','🇸🇬'],['TR','Türkiye','90','🇹🇷'],['AE','United Arab Emirates','971','🇦🇪'],['GB','United Kingdom','44','🇬🇧'],['US','United States','1','🇺🇸']].map(([code,name,dial,flag])=>({code,name,dial,flag}));
let profilePhoneCountryCode='US';
const profileCountry=()=>PROFILE_COUNTRIES.find(c=>c.code===profilePhoneCountryCode)||PROFILE_COUNTRIES.find(c=>c.code==='US');
function profilePhoneField(value){const match=/^\+(\d{1,3})\s*(.*)$/.exec(value||'');if(match){const found=PROFILE_COUNTRIES.find(c=>c.dial===match[1]&&(match[1]!=='1'||c.code==='US'))||PROFILE_COUNTRIES.find(c=>c.dial===match[1]);if(found)profilePhoneCountryCode=found.code;}const country=profileCountry(),national=match?match[2]:value||'';return `<div class="profile-edit-field"><label for="profile-phone">Phone · Optional</label><div class="phone-field"><button type="button" class="phone-country" data-phone-country aria-label="Country code, ${escape(country.name)} +${country.dial}"><span aria-hidden="true">${country.flag}</span>+${country.dial}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></button><input id="profile-phone" name="phone" type="tel" inputmode="tel" autocomplete="tel-national" value="${escape(national)}" placeholder="Phone number" aria-describedby="profile-phone-error"></div><p id="profile-phone-error" class="field-error" hidden></p></div>`;}
function profileCountryRows(query){const q=query.trim().toLowerCase().replace(/^\+/,'');const list=PROFILE_COUNTRIES.filter(c=>!q||c.name.toLowerCase().includes(q)||c.dial.startsWith(q));return list.length?list.map(c=>`<button type="button" class="country-row" data-pick-country="${c.code}" aria-pressed="${c.code===profilePhoneCountryCode}"><span class="country-flag" aria-hidden="true">${c.flag}</span><span class="country-name">${escape(c.name)}</span><span class="country-dial">+${c.dial}</span>${c.code===profilePhoneCountryCode?'<svg class="country-check" viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>':''}</button>`).join(''):'<p class="country-empty">No countries match your search.</p>';}
function openCountrySheet(trigger){const phone=trigger.closest('.phone'),overlay=document.createElement('div');overlay.className='add-overlay reminder-overlay country-overlay';overlay.innerHTML=`<div class="add-sheet-background" data-close-country></div><section class="reminder-sheet country-sheet" role="dialog" aria-modal="true" aria-labelledby="country-title"><div class="handle"></div><header class="add-sheet-header"><div><h3 id="country-title">Select country</h3><p>Used for your phone number’s country code.</p></div><button class="sheet-close" data-close-country aria-label="Close country list">×</button></header><input class="country-search" type="search" placeholder="Search country or code" aria-label="Search country or code" data-country-search><div class="country-list">${profileCountryRows('')}</div></section>`;phone.append(overlay);overlay.querySelector('[data-country-search]').focus();}
document.addEventListener('click',e=>{const open=e.target.closest('[data-phone-country]'),pick=e.target.closest('[data-pick-country]'),close=e.target.closest('[data-close-country]');if(open)openCountrySheet(open);else if(pick){profilePhoneCountryCode=pick.dataset.pickCountry;const c=profileCountry(),button=document.querySelector('[data-phone-country]');if(button){button.setAttribute('aria-label',`Country code, ${c.name} +${c.dial}`);button.innerHTML=`<span aria-hidden="true">${c.flag}</span>+${c.dial}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg>`;}document.querySelector('.country-overlay')?.remove();button?.focus();}else if(close)document.querySelector('.country-overlay')?.remove();});
document.addEventListener('input',e=>{if(e.target.matches('[data-country-search]'))e.target.closest('.country-sheet').querySelector('.country-list').innerHTML=profileCountryRows(e.target.value);});
function profileEditField(label,name,value,type,required=false){return `<div class="profile-edit-field"><label for="profile-${name}">${label}</label><input id="profile-${name}" name="${name}" type="${type}" value="${escape(value)}" ${name==='name'?'placeholder="Your name"':''} ${required?'required':''} ${type==='date'?'max="2026-10-30"':''} aria-describedby="profile-${name}-error"><p id="profile-${name}-error" class="field-error" hidden></p></div>`;}
let connectedInboxOrigin='Connected inbox',connectorPreview={running:false,error:''},connectorPreviewTimer;
function connectedInboxView(){
 const inbox=profileInboxForView();if(!inbox)return null;
 const running=connectorPreview.running||current==='Connected inbox · syncing';
 const reconnect=current==='Connected inbox · reconnect'||inbox.status==='reconnect';
 const error=current==='Connected inbox · error'?'Unable to sync right now. Your saved subscriptions haven’t changed.':connectorPreview.error;
 const status=reconnect?'reconnect':running?'syncing':error?'error':inbox.status==='synced'&&!inbox.lastSync?'pending':inbox.status;
 // Sync runs once a week per inbox (backend SYNC_LIMIT, 13 Nov 2026); until it opens the button says when.
 const locked=!reconnect&&!running&&['Connected inbox · sync locked','Gmail · weekly limit'].includes(current);
 return {inbox,running,reconnect,error,status,locked};
}
function connectedInboxHeader(title='Connected inbox'){return `<div class="head">${backButton({attributes:`data-profile-action="connector-back"`,label:"Back to Profile",className:""})}<h2>${title}</h2></div>`;}
function connectedInboxScreen(){
 const view=connectedInboxView();if(!view)return connectedInboxHeader()+'<p class="note">This inbox is no longer connected.</p>';
 const {inbox,running,reconnect,error,status,locked}=view,imported=profileImportedRecords(inbox.email).length;
 const labels={paused:'Updates paused',pending:'Not synced yet',synced:'Synced',syncing:'Syncing…',reconnect:'Reconnect needed',error:'Sync failed'};
 const main=reconnect?{label:'Reconnect Gmail',action:'reconnect',title:'Reconnect your inbox',copy:'Gmail needs your permission again. Your saved subscriptions are still available.'}:{label:running?'Syncing…':locked?'Sync opens 20 Nov':'Sync now',action:'sync',title:'Keep everything up to date',copy:locked?'You can check this inbox once a week. Renewals you track are still checked.':'Check this inbox for new receipts and subscription updates.'};
 return `<div class="profile-inbox-detail">${connectedInboxHeader()}<div class="profile-inbox-identity">${platformLogo('Gmail')}<h3>${escape(inbox.email)}</h3><span class="inbox-connection-status inbox-state-${status}" ${running?'role="status"':''}>${running?'<i class="inbox-sync-spinner" aria-hidden="true"></i>':''}${labels[status]||'Updates paused'}</span></div><div class="profile-inbox-facts">${fr('Last successful sync',inbox.lastSync||'Not synced yet')}<button class="inbox-imported-link" data-profile-action="imports" aria-label="View ${imported} imported subscriptions"><span>Imported subscriptions</span><strong>${imported}<i aria-hidden="true">›</i></strong></button><div class="fieldrow inbox-access-row">${infoTooltip({id:'inbox-read-access',label:'Mailbox access',paragraphs:['Gmail authorizes read-only access to this inbox. Renewless cannot send, edit or delete your emails.','Relevant receipt details are filtered and may be processed by AI to identify subscriptions. This does not mean Google limits access to receipts only.','You can disconnect at any time. Your saved subscriptions stay.']})}<span>Read-only</span></div></div>${error&&!reconnect?`<div class="inbox-sync-error" role="alert">${escape(error)}</div>`:''}${main?`<section class="profile-sync-info"><strong>${main.title}</strong><p>${main.copy}</p><button class="primary" data-profile-action="${main.action}" ${running||locked?'disabled aria-disabled="true"':''}>${main.label}</button></section>`:''}<button class="profile-disconnect" data-profile-action="disconnect" ${running?'disabled':''}>Disconnect inbox</button><p class="note inbox-disconnect-note">Your saved subscriptions stay. Only new Gmail updates stop.</p></div>`;
}
function inboxSubscriptionsScreen(){
 const inbox=profileInboxForView(),records=inbox?profileImportedRecords(inbox.email):[];
 return `<div class="inbox-imports-layout"><div class="head">${backButton({attributes:`data-profile-action="imports-back"`,label:"Back to connected inbox",className:""})}<h2>Imported subscriptions</h2></div><p class="inbox-imports-email">${escape(inbox?.email||'Inbox disconnected')}</p><p class="note">${records.length} subscription${records.length===1?'':'s'} imported from this inbox.</p>${records.length?`<div class="rows subscription-rows inbox-imported-rows">${records.map(r=>subscriptionCard(r,{attributes:`data-profile-record="${escape(r.id)}" aria-label="View ${escape(r.name)} imported subscription"`})).join('')}</div>`:`<div class="inbox-imports-empty">${mascotView({expression:'neutral',size:96})}<h3>No imported subscriptions</h3><p>Subscriptions imported from this inbox will appear here.</p></div>`}<p class="note">Manually added subscriptions aren’t included here.</p></div>`;
}
function previewInboxSync(){
 if(connectorPreview.running||current==='Connected inbox · syncing')return;
 connectorPreview={running:true,error:''};render();clearTimeout(connectorPreviewTimer);
 connectorPreviewTimer=setTimeout(()=>{connectorPreview={running:false,error:'Unable to sync right now. Your saved subscriptions haven’t changed.'};if(current.startsWith('Connected inbox'))render();},1200);
}
function closeProfileDialog(phone){if(phone.querySelector('[data-delete-account][data-stage=deleting]'))return;profileDeleteEpoch++;phone.querySelector('.profile-dialog-overlay')?.remove();phone.querySelectorAll('[data-profile-dialog-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-profile-dialog-inert');});profileDialogTrigger?.focus();profileDialogTrigger=null;}
function openProfileDialog(trigger,type){if(type==='delete-account'){openDeleteAccountDialog(trigger);return;}const phone=trigger.closest('.phone'),disconnect=type==='disconnect',limit=type==='inbox-limit',overlay=document.createElement('div');profileDialogTrigger=trigger;overlay.className='profile-dialog-overlay';overlay.innerHTML=`<div class="profile-dialog-shade" data-close-profile-dialog></div><section class="profile-dialog" role="dialog" aria-modal="true" aria-labelledby="profile-dialog-title"><header><h3 id="profile-dialog-title">${disconnect?'Disconnect this inbox?':limit?'You’ve used your 2 Gmail inboxes':'Log out of Renewless?'}</h3><button data-close-profile-dialog aria-label="Close confirmation">×</button></header><p>${disconnect?'Your saved subscriptions stay. We’ll stop reading this inbox. It still counts toward your 2 Gmail inboxes, and you can reconnect it anytime.':limit?'That’s the limit for now. You can reconnect an inbox you used before.':'Your saved subscriptions stay on your account. You can sign in again anytime.'}</p><div>${limit?'<button class="primary" data-close-profile-dialog>OK</button>':`<button class="secondary" data-close-profile-dialog>Cancel</button><button class="profile-confirm-danger" data-confirm-profile="${type}">${disconnect?'Disconnect':'Log out'}</button>`}</div></section>`;phone.append(overlay);[...phone.children].filter(el=>el!==overlay&&!el.inert).forEach(el=>{el.inert=true;el.dataset.profileDialogInert='true';});overlay.querySelector('button').focus();}
function resetProfilePreview(){clearTimeout(connectorPreviewTimer);connectorPreview={running:false,error:''};connectedInboxOrigin='Connected inbox';profileData={name:'Alex Morgan',email:'alex@example.com',phone:'+1 202 555 0143',dateOfBirth:'1993-03-14',gender:'Not set'};profileInboxes=[{id:'gmail-alex',email:'alex@example.com',status:'synced',lastSync:'26 Oct · 9:00 AM'}];profileReviewOrigin='Profile';profileDialogTrigger=null;}
document.addEventListener('click',event=>{const button=event.target.closest('[data-profile-action]'),close=event.target.closest('[data-close-profile-dialog]'),confirm=event.target.closest('[data-confirm-profile]');if(button){const name=button.dataset.profileAction;if(name==='edit')go('Edit profile');else if(name==='inbox')go('Connected inbox');else if(name==='connector-back')go(profileReviewOrigin);else if(name==='imports'){connectedInboxOrigin=current;go('Inbox subscriptions');}else if(name==='imports-back')go(connectedInboxOrigin);else if(name==='sync'){const inbox=profileInboxForView();if(inbox)gmailReview.email=inbox.email;go('Gmail · scanning');}else if(name==='reconnect'){profileInboxes=profileInboxes.map((inbox,index)=>index?inbox:{...inbox,status:'synced'});go('Connected inbox');}else if(name==='connect'){if(current==='Profile · inbox limit'||profileInboxes.length>=2)openProfileDialog(button,'inbox-limit');else go('Gmail · scanning');}else if(name==='logout'||name==='disconnect'||name==='delete-account')openProfileDialog(button,name);else if(name==='provider')toast('You sign in with Google. Manage your password through your Google account.');else toast(name==='support'?'Support is currently unavailable. Please try again later.':'This page isn’t available yet.');}else if(close)closeProfileDialog(close.closest('.phone'));else if(confirm){if(confirm.dataset.confirmProfile==='disconnect'){const inbox=profileInboxes[0];if(inbox){profileInboxes=profileInboxes.filter(r=>r.id!==inbox.id);}go(profileReviewOrigin);toast('Inbox disconnected. Your saved subscriptions stay.');}else{ob.account=false;go('Login');toast('You’re logged out.');}profileDialogTrigger=null;}});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-profile-edit]');if(!form)return;event.preventDefault();form.querySelectorAll('.field-error').forEach(el=>el.hidden=true);form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));const name=form.elements.name.value.trim(),dob=form.elements.dateOfBirth.value;let field=null,message='';if(!name){field=form.elements.name;message='Enter your name.';}else if(dob&&dob>'2026-10-30'){field=form.elements.dateOfBirth;message='Choose a date in the past.';}if(field){const error=form.querySelector('#'+field.id+'-error');error.textContent=message;error.hidden=false;field.setAttribute('aria-invalid','true');field.focus();return;}profileData={...profileData,name,phone:form.elements.phone.value.trim()?'+'+profileCountry().dial+' '+form.elements.phone.value.trim():'',dateOfBirth:dob,gender:form.elements.gender.value};go(profileReviewOrigin);toast('Profile updated.');});
document.addEventListener('keydown',event=>{const overlay=document.querySelector('.profile-dialog-overlay');if(!overlay)return;if(event.key==='Escape'){event.preventDefault();closeProfileDialog(overlay.closest('.phone'));}else if(event.key==='Tab'){const controls=[...overlay.querySelectorAll(overlay.classList.contains('profile-delete-overlay')?'button:not([disabled]),input:not([disabled])':'button')],first=controls[0],last=controls[controls.length-1];if(!controls.length){event.preventDefault();return;}if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});

document.addEventListener('click',event=>{const row=event.target.closest('[data-profile-record]');if(!row)return;const r=subscriptionListData().find(item=>item.id===row.dataset.profileRecord);if(!r){toast('This subscription is no longer available.');return;}state.manual={...r};demoName=r.name;demoPrice=r.price;go('Detail');});

/* Password-change preview. Never persists credentials or claims a live password update. */
function changePasswordErrors(values){
 const errors={};
 if(!values.currentPassword)errors.currentPassword='Enter your current password.';
 if(!values.newPassword)errors.newPassword='Enter a new password.';
 else if(values.newPassword.length<8)errors.newPassword='Use at least 8 characters.';
 else if(values.newPassword===values.currentPassword)errors.newPassword='Choose a password different from your current one.';
 if(!values.confirmPassword)errors.confirmPassword='Confirm your new password.';
 else if(values.confirmPassword!==values.newPassword)errors.confirmPassword='Passwords don’t match.';
 return errors;
}
function changePasswordField(label,name,autocomplete){return `<div class="cp-field"><label for="cp-${name}">${label}</label><div class="cp-input-wrap"><input id="cp-${name}" name="${name}" type="password" autocomplete="${autocomplete}" placeholder="${{currentPassword:'Enter your current password',newPassword:'At least 8 characters',confirmPassword:'Re-enter your password'}[name]}" autocapitalize="none" spellcheck="false" required ${name==='currentPassword'?'':'minlength="6"'} aria-describedby="cp-${name}-error${name==='newPassword'?' cp-password-hint':''}"><button type="button" class="cp-visibility" data-cp-visibility="${name}" aria-label="Show ${label.toLowerCase()}" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/><path class="cp-eye-slash" d="m4 3 16 18"/></svg></button></div>${name==='newPassword'?'<p class="cp-hint" id="cp-password-hint">Use at least 8 characters.</p>':''}<p class="field-error" id="cp-${name}-error" aria-live="polite" hidden></p></div>`;}
function changePasswordScreen(){
 const header=`<div class="head cp-head">${backButton({attributes:`data-cp-back`,label:"Back to Profile",className:""})}<h2>Change password</h2></div>`;
 if(!profileContext().hasPassword)return `<div class="change-password-review">${header}<section class="cp-provider"><span class="cp-security-icon">${profileIcon('security')}</span><h3>You sign in with Google</h3><p>Your Google account manages your password. You don’t need a separate Renewless password.</p><button class="secondary" data-cp-back>Back to Profile</button></section></div>`;
 return `<div class="change-password-review">${header}<div class="cp-intro"><span class="cp-security-icon">${profileIcon('security')}</span><h3>A fresh password.<br>A little more peace of mind.</h3><p>Update the password you use to sign in to Renewless.</p></div><form id="change-password-form" data-change-password novalidate>${changePasswordField('Current password','currentPassword','current-password')}${changePasswordField('New password','newPassword','new-password')}${changePasswordField('Confirm new password','confirmPassword','new-password')}<div class="cp-request-error" role="alert" hidden></div></form><div class="password-change-footer"><button class="primary" form="change-password-form" type="submit">Update password</button><p>Your tracked subscriptions stay unchanged.</p></div></div>`;
}
function changePasswordValues(form){return {currentPassword:form.elements.currentPassword.value,newPassword:form.elements.newPassword.value,confirmPassword:form.elements.confirmPassword.value};}
function showChangePasswordErrors(form,errors,focusFirst=false){for(const name of ['currentPassword','newPassword','confirmPassword']){const field=form.elements[name],error=form.querySelector('#cp-'+name+'-error'),message=errors[name]||'';error.textContent=message;error.hidden=!message;field.setAttribute('aria-invalid',String(!!message));}if(focusFirst){const first=Object.keys(errors)[0];if(first)form.elements[first].focus();}}
document.addEventListener('click',event=>{const eye=event.target.closest('[data-cp-visibility]'),back=event.target.closest('[data-cp-back]');if(back){go(profileReviewOrigin);return;}if(!eye)return;const form=eye.closest('form'),field=form.elements[eye.dataset.cpVisibility],show=field.type==='password';field.type=show?'text':'password';eye.setAttribute('aria-pressed',String(show));eye.setAttribute('aria-label',(show?'Hide ':'Show ')+field.closest('.cp-field').querySelector('label').textContent.toLowerCase());field.focus();});
document.addEventListener('input',event=>{const form=event.target.closest('[data-change-password]');if(!form)return;form.querySelector('.cp-request-error').hidden=true;if(form.dataset.submitted)showChangePasswordErrors(form,changePasswordErrors(changePasswordValues(form)));});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-change-password]');if(!form)return;event.preventDefault();if(form.dataset.busy==='true')return;form.dataset.submitted='true';const errors=changePasswordErrors(changePasswordValues(form));showChangePasswordErrors(form,errors,true);const requestError=form.querySelector('.cp-request-error');requestError.hidden=true;if(Object.keys(errors).length)return;form.dataset.busy='true';form.setAttribute('aria-busy','true');const button=form.closest('.phone').querySelector('.password-change-footer button');button.disabled=true;button.textContent='Updating…';form.querySelectorAll('input,.cp-visibility').forEach(el=>el.disabled=true);setTimeout(()=>{if(!form.isConnected)return;form.dataset.busy='false';form.removeAttribute('aria-busy');form.querySelectorAll('input,.cp-visibility').forEach(el=>el.disabled=false);button.disabled=false;button.textContent='Update password';requestError.textContent='Unable to update your password right now. Please try again.';requestError.hidden=false;},1000);});

/* Account-deletion design preview only. Intent text is not identity verification. */
let profileDeleteEpoch=0;
const deleteAccountReady=form=>form.elements.confirmation.value.trim()==='DELETE'&&(!form.elements.password||!!form.elements.password.value);
async function performAccountDeletion({verify,remove,isCurrent=()=>true}){try{const auth=await verify();if(!isCurrent())return {status:'obsolete'};if(!auth?.verified)return {status:'cancelled'};const result=await remove();if(!isCurrent())return {status:'obsolete'};return result?.deleted?{status:'deleted'}:{status:'failed'};}catch(error){return {status:isCurrent()?'failed':'obsolete'};}}
// Email accounts confirm with their password; Google/Apple verify in the provider sheet (native, 13 Nov 2026).
function openDeleteAccountDialog(trigger){const phone=trigger.closest('.phone'),password=profileContext().hasPassword,overlay=document.createElement('div');profileDialogTrigger=trigger;profileDeleteEpoch++;overlay.className='profile-dialog-overlay profile-delete-overlay';overlay.innerHTML=`<div class="profile-dialog-shade" data-close-profile-dialog></div><section class="profile-dialog profile-delete-dialog" role="dialog" aria-modal="true" aria-labelledby="profile-dialog-title" aria-describedby="delete-account-description"><header><h3 id="profile-dialog-title">Delete your Renewless account?</h3><button data-close-profile-dialog aria-label="Close deletion confirmation">×</button></header><p id="delete-account-description">This permanently removes your account and saved tracking data, disconnects your Gmail inboxes and stops Renewless reminders.</p><p class="profile-delete-provider-note">Your subscriptions with other services won’t be cancelled.</p><p class="profile-delete-verification">${password?'Enter your password and type DELETE to confirm.':'We’ll ask you to verify your sign-in before deleting your account.'}</p><form data-delete-account novalidate>${password?'<label for="delete-account-password">Password<input id="delete-account-password" name="password" type="password" placeholder="Enter your password" autocomplete="current-password" aria-describedby="delete-account-error"></label>':''}<label for="delete-account-confirm">Type DELETE to confirm<input id="delete-account-confirm" name="confirmation" type="text" placeholder="DELETE" autocomplete="off" spellcheck="false" autocapitalize="characters" aria-describedby="delete-account-error"></label><p id="delete-account-error" class="field-error" role="alert" hidden></p><div class="profile-dialog-actions"><button type="button" class="secondary" data-close-profile-dialog>Keep account</button><button type="submit" class="profile-confirm-danger" data-delete-account-submit disabled>Delete account</button></div></form></section>`;phone.append(overlay);[...phone.children].filter(el=>el!==overlay&&!el.inert).forEach(el=>{el.inert=true;el.dataset.profileDialogInert='true';});overlay.querySelector('[data-close-profile-dialog]').focus();}
function clearDeletedAccountPreview(){clearTimeout(connectorPreviewTimer);connectorPreview={running:false,error:''};resetAppNavigation();resetAiTextChats();resetAuthenticatedGmail();resetDetailEnhancements();resetOnboardingConnection();resetAccountReminders();trialRecords.clear();paymentRecords.clear();reminderPreferences.clear();profileInboxes=[];profileData={name:'',email:'',phone:'',dateOfBirth:'',gender:'Not set'};profileDialogTrigger=null;ob.dashboardActive=true;ob.savedRecords={};go('Login');try{sessionStorage.removeItem('renewless-onboarding-preview-v2');}catch(error){}toast('Account deleted.');}
async function deleteProfileAccount(form,{verify,remove}={}){if(form.dataset.stage)return;if(!deleteAccountReady(form))return;const epoch=profileDeleteEpoch,owner=ob.accountId||profileData.email,button=form.querySelector('[data-delete-account-submit]'),input=form.elements.confirmation,error=form.querySelector('.field-error'),overlay=form.closest('.profile-dialog-overlay');const current=()=>epoch===profileDeleteEpoch&&overlay.isConnected&&(ob.accountId||profileData.email)===owner;form.dataset.stage='verifying';button.disabled=true;input.disabled=true;button.textContent='Verifying…';error.hidden=true;
 const outcome=await performAccountDeletion({isCurrent:current,verify:verify||(()=>new Promise(resolve=>setTimeout(()=>resolve({verified:true}),400))),remove:()=>{form.dataset.stage='deleting';button.textContent='Deleting…';overlay.querySelectorAll('[data-close-profile-dialog]').forEach(el=>el.disabled=true);return remove?remove():new Promise(resolve=>setTimeout(()=>resolve({deleted:true}),450));}});
 if(outcome.status==='obsolete')return;if(outcome.status==='deleted'){profileDeleteEpoch++;clearDeletedAccountPreview();return;}form.dataset.stage='';button.disabled=false;input.disabled=false;button.textContent='Delete account';overlay.querySelectorAll('[data-close-profile-dialog]').forEach(el=>el.disabled=false);error.textContent=outcome.status==='cancelled'?'Verification was cancelled. Your account hasn’t been deleted.':'We couldn’t delete your account. Please try again.';error.hidden=false;input.focus();}
document.addEventListener('input',event=>{const form=event.target.closest('[data-delete-account]');if(!form||form.dataset.stage)return;form.querySelector('[data-delete-account-submit]').disabled=!deleteAccountReady(form);});
document.addEventListener('submit',event=>{if(!event.target.matches('[data-delete-account]'))return;event.preventDefault();deleteProfileAccount(event.target);});

// Settings (locked 8 Nov 2026): preferences, AI assistant consent, widget help, account and legal moved out of Profile.
let settingsAiEnabled=true;
function settingsScreen(){const ctx=profileContext();return `<div class="profile-review settings-review">${heading('Settings',true)}<section class="profile-menu-section" aria-label="Notifications"><h3>Notifications</h3><div class="profile-menu-group">${profileMenuRow('Reminder settings','refresh',{to:'Reminder settings',subtitle:'When and how you’re reminded'})}</div></section><section class="profile-menu-section" aria-label="AI assistant"><h3>AI assistant</h3><div class="reminder-settings-group"><label class="account-reminder-toggle"><span><strong>Use Google Gemini</strong><small>AI chat sends your messages, voice notes, images and PDFs to Google Gemini to suggest subscription details.</small></span><input type="checkbox" role="switch" data-settings-ai aria-label="Use Google Gemini" ${settingsAiEnabled?'checked':''}></label></div><p class="settings-note">${settingsAiEnabled?'You can turn this off at any time.':'AI chat will ask before you use it again.'} <button class="settings-link" data-profile-action="privacy">How we use your data ›</button></p></section><section class="profile-menu-section" aria-label="Home Screen widget"><h3>Home Screen widget</h3><div class="profile-menu-group">${profileMenuRow('Add the widget','widget',{to:'Home · add widget',subtitle:'See your next renewal without opening the app'})}</div></section><section class="profile-menu-section" aria-label="Account"><h3>Account</h3><div class="profile-menu-group">${ctx.hasPassword?profileMenuRow('Change password','security',{to:'Change password'}):profileMenuRow('Sign-in method','security',{action:'provider',subtitle:'Google account'})}${profileMenuRow('Delete account','delete',{action:'delete-account',tone:'settings-danger'})}</div></section><section class="profile-menu-section" aria-label="Legal"><h3>Legal</h3><div class="profile-menu-group">${profileMenuRow('Privacy Policy','privacy',{action:'privacy'})}${profileMenuRow('Terms of Service','terms',{action:'terms'})}</div></section></div>`;}
document.addEventListener('change',e=>{if(e.target.matches('[data-settings-ai]')){settingsAiEnabled=e.target.checked;render();}});

// Backend integration states (native, 13 Nov 2026; pending review): notices that stay up on their inspection route,
// the email Delete account dialog and AI chat's already-tracked question.
let integrationNoticePinned=false;
function integrationStatesAfterRender(){
 const notice={'Home · inbox scanned before':'This inbox was scanned before, so it isn’t scanned again. Add your subscriptions again. Sync opens on 20 Nov and reads mail from 13 Nov.','Gmail · weekly limit':'You can sync this inbox once a week.'}[current];
 const t=document.getElementById('toast');
 if(notice){t.textContent=notice;t.hidden=false;clearTimeout(toastTimer);integrationNoticePinned=true;}
 else if(integrationNoticePinned){t.hidden=true;integrationNoticePinned=false;}
 if(current==='Delete account · email'){const trigger=document.querySelector('[data-variant=upgraded] [data-profile-action=delete-account]');if(trigger)openDeleteAccountDialog(trigger);}
 aiDuplicateOverlay(current==='AI chat · already tracked');
}

// Home empty, Gmail first (Gmail hero, locked 13 Nov 2026): Connect Gmail in the onboarding style, with onboarding's
// Gmail → Renewless art and trust rows, then Add with AI · Add manually. When the connected inbox can't sync yet
// (Home · inbox scanned before) there is no Connect Gmail: the card gives the sync date and offers AI, manual entry and
// another inbox instead (approved and locked by the user, 13 Nov 2026).
function homeGmailPromo(){
 const art=`<div class="ob-connect-art" role="img" aria-label="Connect Gmail to Renewless"><div class="ob-connection-brand"><span class="ob-connection-tile">${platformLogo('Gmail')}</span><span class="ob-connection-label">Gmail</span></div><svg class="ob-connection-arrow" viewBox="0 0 48 24" aria-hidden="true"><path d="M4 12h38m-7-7 7 7-7 7"/></svg><div class="ob-connection-brand"><span class="ob-connection-tile"><img src="assets/renewless-mark.svg" alt=""></span><span class="ob-connection-label">Renewless</span></div></div>`;
 if(current==='Home · inbox scanned before')return `<div class="gmail-promo gmail-promo-locked">${art}<span class="gmail-sync-pill"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>Next sync · 20 Nov</span><h3>Your inbox was checked recently</h3><p class="gmail-promo-copy">alex.receipts@gmail.com syncs once a week. Until then, you can still add subscriptions:</p><div class="add-options gmail-promo-options"><button class="add-option" data-go="Gmail · scanning"><span class="add-option-icon">${platformLogo('Gmail')}</span><span class="add-option-copy"><strong>Connect another Gmail</strong><small>Find subscriptions in a second inbox</small></span><span class="add-chevron" aria-hidden="true">›</span></button><button class="add-option add-option-ai" data-go="AI chat"><span class="add-option-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4z"/></svg></span><span class="add-option-copy"><strong>Add with AI</strong><small>Type, speak, or share a screenshot</small></span><span class="add-chevron" aria-hidden="true">›</span></button><button class="add-option" data-go="Add form"><span class="add-option-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 4 5 5M4 20l5-1L21 7l-4-4L5 15z"/></svg></span><span class="add-option-copy"><strong>Add manually</strong><small>Enter your subscription details</small></span><span class="add-chevron" aria-hidden="true">›</span></button></div></div>`;
 return `<div class="gmail-promo">${art}<h3>Let Loop find your subscriptions</h3><p class="gmail-promo-copy">Connect Gmail and Loop lists what you pay for from your receipts. It takes about a minute.</p><div class="ob-trust gmail-promo-trust-rows">${fr('Read-only access','We can’t send or delete emails')}${fr('You’re in control','Review before saving')}${fr('Scans & updates','Free to use')}</div><div class="gmail-promo-actions"><button class="primary gmail-promo-cta" data-go="Gmail · scanning">Connect Gmail</button>${addChoiceLinks()}</div></div>`;
}
